from datetime import datetime,timezone,timedelta
now=datetime.now(timezone.utc)
evaluate('window.powerTestFeed=window.CityControlNativeFeed;window.CityControlNativeFeed=()=>{};true')
end=now-timedelta(hours=35)
e={'id':'retention-power','category':'power','sourceId':'power_direct','origin':'official_site','url':'https://donenergo.ru/grafik-otklyucheniy/61/1/','kind':'planned','status':'unconfirmed','title':'Проверка сохранения света','affected':[{'street':'ул Тестовая','houses':['12']}],'start':(end-timedelta(hours=3)).isoformat(),'end':end.isoformat(),'lastConfirmedAt':end.isoformat(),'retainUntil':(end+timedelta(hours=36)).isoformat(),'retained':True}
f={'schema':2,'checkedAt':now.isoformat(),'sources':[{'id':'power_direct','status':'error','checkedAt':now.isoformat(),'note':'HTTP 500'}],'events':[e]}
def inject_power():evaluate('powerTestFeed('+json.dumps(f,ensure_ascii=False)+')')
inject_power()
check(evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'Power survives HTTP 500 and 35 hours after scheduled end')
evaluate('CityMapV07.openDetails('+json.dumps(e,ensure_ascii=False)+')')
check(evaluate("document.querySelector('#cityEventBody').textContent.includes('Последняя сохранённая публикация')"),'Retained power discloses cached provenance')
evaluate("document.querySelector('#cityEventClose').click()")
e['status']='resolved';inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'Explicit restoration removes power marker immediately')
e['status']='unconfirmed';e['end']=(now-timedelta(hours=37)).isoformat();e['retainUntil']=(now-timedelta(hours=1)).isoformat();inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'Power expires after 36 hours without extending on refresh')
e['end']=end.isoformat();e['retainUntil']=(end+timedelta(hours=36)).isoformat();e['url']='https://example.org/unverified';inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'Retention never accepts untrusted source URL')
e.update(sourceId='max_power',origin='official_max',url='https://max.ru/id6163089292_biz',requiresReview=False)
f['sources']=[{'id':'max_power','status':'error','checkedAt':now.isoformat(),'note':'MAX temporarily unavailable'}]
inject_power()
check(evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'Verified MAX power survives a source error for 35 hours')
e['status']='resolved';inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'MAX restoration removes the marker immediately')
e['status']='unconfirmed';e['requiresReview']=True;inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'MAX review candidate cannot create a marker')
e['requiresReview']=False;e['sourceId']='max_city';inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'MAX source identity must match its channel URL')
e.update(sourceId='max_power',end=(now-timedelta(hours=37)).isoformat(),retainUntil=(now-timedelta(hours=1)).isoformat());inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('retention-power')"),'MAX markers expire at the original 36-hour deadline')
water={**e,'id':'max-water-test','category':'water','sourceId':'max_city','url':'https://max.ru/shakhtygorod','start':(now-timedelta(hours=1)).isoformat(),'end':(now+timedelta(hours=1)).isoformat(),'status':'active'}
water.pop('lastConfirmedAt',None);water.pop('retainUntil',None);water['retained']=False
f['events']=[water];f['sources']=[{'id':'max_city','status':'ok','checkedAt':now.isoformat()}];inject_power()
check(evaluate("CityMapV07.inspect().allIds.includes('max-water-test')"),'Verified current MAX water appears on the installed map')
check(evaluate("document.querySelector('#sourcesGrid').textContent.includes('MAX · Донэнерго')"),'MAX source visibly listed without claiming connected access')
check(evaluate("document.querySelectorAll('#sourcesGrid .source').length")==15,'All fifteen source entries present exactly once')
water.update(id='ursv-max-water-test',sourceId='max_water',url='https://max.ru/id6167110467_gos')
f['events']=[water];f['sources']=[{'id':'max_water','status':'ok','checkedAt':now.isoformat()}];inject_power()
check(evaluate("CityMapV07.inspect().allIds.includes('ursv-max-water-test')"),'Official URSV MAX water accepted with its own source identity')
f['sources'][0]['status']='error';inject_power()
check(not evaluate("CityMapV07.inspect().allIds.includes('ursv-max-water-test')"),'Failed URSV source cannot validate new water notices')
evaluate('window.CityControlNativeFeed=window.powerTestFeed;true')
